const TABLES = ["design_progress", "design_attempts"];
const TEMP = "~moving~";

async function applyMoves(qi, moves) {
  const { sequelize } = qi;
  await sequelize.transaction(async (transaction) => {
    const q = (sql, replacements) => sequelize.query(sql, { replacements, transaction });
    const select = (sql, replacements) => sequelize.query(sql, { replacements, transaction, type: sequelize.QueryTypes.SELECT });
    for (const table of TABLES) {
      // 1. Park every row that moves under a temporary id, so no rename can collide with another.
      for (const [from] of moves) await q(`UPDATE ${table} SET question_id = :temp WHERE question_id = :from`, { temp: TEMP + from, from });
      // 2. Give each parked row its new id; if the student already has a row there, merge into it.
      for (const [from, to] of moves) {
        const parked = await select(`SELECT * FROM ${table} WHERE question_id = :temp`, { temp: TEMP + from });
        for (const row of parked) {
          const [existing] = await select(`SELECT * FROM ${table} WHERE user_id = :userId AND question_id = :to`, { userId: row.user_id, to });
          if (!existing) {
            await q(`UPDATE ${table} SET question_id = :to WHERE id = :id`, { to, id: row.id });
            continue;
          }
          if (table === "design_attempts" && row.notes) {
            const notes = existing.notes ? `${existing.notes}\n\n${row.notes}` : row.notes;
            await q(`UPDATE design_attempts SET notes = :notes WHERE id = :id`, { notes, id: existing.id });
          }
          await q(`DELETE FROM ${table} WHERE id = :id`, { id: row.id });
        }
      }
    }
  });
}

export async function up({ context: qi }) {
  await applyMoves(qi, MOVES);
}

// Best effort: merged practice notes stay with the first of the old days.
export async function down({ context: qi }) {
  const seen = new Set();
  const back = MOVES.map(([from, to]) => [to, from]).filter(([from]) => !seen.has(from) && seen.add(from));
  await applyMoves(qi, back);
}
